package com.jobpilot.api.domain.review.service;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import static org.assertj.core.api.Assertions.*;
@EnabledIfSystemProperty(named="review.mysql.url",matches="jdbc:mysql://127\\.0\\.0\\.1:33379/review_schema_[a-f0-9]+.*")class FictionalDemoSeederMysqlTest{
 @Test void seedsExactCardinalityTwiceWithoutTouchingExistingRows(){var ds=new DriverManagerDataSource(System.getProperty("review.mysql.url"),"root","");var db=new JdbcTemplate(ds);assertThat(db.queryForObject("SELECT @@datadir",String.class).replace('\\','/').toLowerCase()).startsWith("c:/final_project/tmp/review-schema-mysql-");var seeder=new FictionalDemoSeeder(db,new DataSourceTransactionManager(ds),"https://demo.invalid",0L);seeder.seed();seeder.seed();assertThat(db.queryForObject("SELECT COUNT(*) FROM review_companies WHERE seed_key LIKE 'DEMO-COMPANY-%'",Long.class)).isEqualTo(100);assertThat(db.queryForObject("SELECT COUNT(*) FROM job_postings WHERE external_job_id LIKE 'DEMO-JOB-%'",Long.class)).isEqualTo(100);assertThat(db.queryForObject("SELECT COUNT(*) FROM company_reviews WHERE seed_key LIKE 'DEMO-REVIEW-%'",Long.class)).isEqualTo(500);assertThat(db.queryForObject("SELECT source_provider FROM job_postings WHERE id=10",String.class)).isEqualTo("TEST");db.update("UPDATE company_reviews SET next_analysis_at=NULL WHERE seed_key LIKE 'DEMO-REVIEW-%'");}
}
